<?php
require_once __DIR__.'/../config/database.php';require_once __DIR__.'/../includes/auth.php';require_sales_access();$page_title='Meetings';$current_page='meetings';$params=[];$vis=lead_visibility_sql($params,'l');$q=$pdo->prepare("SELECT m.*,l.name,l.company FROM meetings m JOIN leads l ON l.id=m.lead_id WHERE 1=1$vis ORDER BY m.meeting_date DESC,m.start_time DESC LIMIT 150");$q->execute($params);$rows=$q->fetchAll();require __DIR__.'/../includes/header.php';?><div class="section-card"><div class="section-head"><h2>Meetings</h2><a class="btn btn-primary" href="schedule_meeting.php">+ Schedule Meeting</a></div><div class="table-wrap"><table class="table"><thead><tr><th>Date</th><th>Meeting</th><th>Lead</th><th>Time</th><th>Status</th><th></th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="6" class="empty">No meetings yet.</td></tr><?php else:foreach($rows as $m):?><tr><td><?=e(format_day($m['meeting_date']))?></td><td><?=e($m['title'])?></td><td><a href="lead.php?id=<?=$m['lead_id']?>"><strong><?=e($m['company']?:$m['name'])?></strong></a></td><td><?=e(date('h:i A',strtotime($m['start_time'])))?><?php if($m['end_time']):?> – <?=e(date('h:i A',strtotime($m['end_time'])))?><?php endif;?></td><td><span class="badge <?=$m['status']==='Done'?'badge-green':($m['status']==='Cancelled'?'badge-red':'badge-blue')?>"><?=e($m['status'])?></span></td><td><a class="btn btn-light btn-sm" href="meeting.php?id=<?=$m['id']?>">Open</a></td></tr><?php endforeach;endif;?></tbody></table></div></div><?php require __DIR__.'/../includes/footer.php'; ?>